package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Formats a stored E.164 telephone for human display: the country code, a space, then the national
 * digits grouped in threes. So {@code '+61412345678'} becomes {@code '+61 412 345 678'} and
 * {@code '+14155550101'} becomes {@code '+1 415 555 0101'}.
 *
 * <p>The raw stored value keeps its E.164 form; this derives the {@code telephoneDisplay} field at
 * read time. The country code split mirrors {@link E164Telephone}: '+1' (NANP) is a single digit,
 * every other code is treated as two digits (this app defaults to '+61').
 */
public final class TelephoneDisplay {

    private TelephoneDisplay() {
    }

    /** The human-readable display form of a stored owner's telephone. */
    public static String of(Owner owner) {
        return format(owner.getTelephone());
    }

    /** Format an E.164 number for display, or return it unchanged when it is not E.164. */
    static String format(String e164) {
        if (e164 == null || !e164.startsWith("+") || !e164.substring(1).matches("\\d+")) {
            return e164;
        }
        String digits = e164.substring(1);
        int ccLen = digits.startsWith("1") ? 1 : 2;
        if (digits.length() <= ccLen) {
            return e164;
        }
        String countryCode = digits.substring(0, ccLen);
        String national = digits.substring(ccLen);
        StringBuilder groups = new StringBuilder();
        for (int i = 0; i < national.length(); i += 3) {
            if (groups.length() > 0) {
                groups.append(' ');
            }
            groups.append(national, i, Math.min(i + 3, national.length()));
        }
        return "+" + countryCode + " " + groups;
    }
}

